    inline constexpr auto Pins = []() constexpr
    {
        std::array<Pin, NativeModelVehicleNamedProfile::Pins.size() + 5> pins{};
        for (std::size_t index = 0; index < NativeModelVehicleNamedProfile::Pins.size(); ++index)
        {
            const auto& value = NativeModelVehicleNamedProfile::Pins[index];
            pins[index] = {value.rva, value.bytes, value.size, value.rva == NativeModelVehicleNamedProfile::ProducerRva};
        }
        pins[NativeModelVehicleNamedProfile::Pins.size()] = {FormatRva, Format.data(), Format.size(), false};
        pins[NativeModelVehicleNamedProfile::Pins.size() + 1] = {ConsumerRva, Consumer.data(), Consumer.size(), true};
        pins[NativeModelVehicleNamedProfile::Pins.size() + 2] = {PoolConstructorRva, PoolConstructor.data(), PoolConstructor.size(), true};
        pins[NativeModelVehicleNamedProfile::Pins.size() + 3] = {InitializeRva, Initialize.data(), Initialize.size(), true};
        pins[NativeModelVehicleNamedProfile::Pins.size() + 4] = {TypeGetterRva, Type.data(), Type.size(), true};
        return pins;
    }();
